// The DL7 tree-sitter grammar; `src/parser.c` is generated by `tree-sitter generate`.
fn main() {
    let src = std::path::Path::new("tree-sitter-dl7/src");
    let parser = src.join("parser.c");
    println!("cargo:rerun-if-changed={}", parser.display());
    cc::Build::new()
        .include(src)
        .file(&parser)
        .warnings(false)
        .compile("tree_sitter_dl7");
}
